sealed class FcoDonorRig:IDisposable {
 internal GameObject Body;internal BodyBones Bones;internal Animator Animator;internal SkinnedMeshRenderer Skin;internal Wear Authored;internal PlayableGraph Graph;internal AnimationPlayableOutput Output;internal AnimationClipPlayable Play;
 internal FcoDonorRig(GameObject asset,ActorName actor=ActorName.Kshishtof){Authored=asset.GetComponent<Wear>();Body=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(PeopleRoot+"/Prefabs/Actors/"+actor+".prefab"));Body.hideFlags=HideFlags.HideAndDontSave;Body.transform.localScale=Vector3.one*.7764706f;Animator=Body.GetComponent<Animator>();Animator.enabled=false;Bones=Body.GetComponent<BodyBones>();Bones.Construct(actor,649);Bones.Equip("fco-evidence-briefs",AssetDatabase.LoadAssetAtPath<GameObject>(PeopleRoot+"/Prefabs/Wear/"+actor+"_PrimalBriefs.prefab").GetComponent<Wear>(),null);Equip();Animator.runtimeAnimatorController=null;Animator.enabled=true;Animator.applyRootMotion=false;Animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;Animator.Rebind();Graph=PlayableGraph.Create("FCO original donor evidence");Graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);Output=AnimationPlayableOutput.Create(Graph,"real imported humanoid clips",Animator);}
