 internal void BeginPose(AnimationClip clip,float time,bool laying){if(Play.IsValid())Graph.DestroyPlayable(Play);Play=AnimationClipPlayable.Create(Graph,clip);Output.SetSourcePlayable(Play);Graph.Play();Play.SetTime(clip.length*time);Graph.Evaluate(0);Bones.SetHeelPoseSuppressed(laying);}
 internal int Pose(AnimationClip clip,float time,bool laying){BeginPose(clip,time,laying);int calls=0;float target=laying?0:1;var late=typeof(BodyBones).GetMethod("LateUpdate",BindingFlags.Instance|BindingFlags.NonPublic);while(Mathf.Abs(Bones.HeelPoseWeight-target)>.001f&&calls<128){Graph.Evaluate(0);late.Invoke(Bones,null);calls++;if(Time.unscaledDeltaTime<=0)throw new InvalidOperationException("Actual heel transition has zero deltaTime; run this diagnostic with active Editor/PlayMode ticks, never force private heel fields");}if(Mathf.Abs(Bones.HeelPoseWeight-target)>.001f)throw new InvalidOperationException("Actual heel pose did not settle");Graph.Evaluate(0);late.Invoke(Bones,null);return calls+1;}
 public void Dispose(){if(Graph.IsValid())Graph.Destroy();if(Body!=null)Object.DestroyImmediate(Body);}
