static Mesh FcoDonorCapture(SkinnedMeshRenderer skin){var mesh=new Mesh();skin.BakeMesh(mesh,true);var matrix=skin.transform.localToWorldMatrix;var normal=matrix.inverse.transpose;mesh.vertices=mesh.vertices.Select(matrix.MultiplyPoint3x4).ToArray();mesh.normals=mesh.normals.Select(n=>normal.MultiplyVector(n).normalized).ToArray();mesh.RecalculateBounds();return mesh;}
static JObject FcoDonorFreshQuality(Mesh native,Mesh candidate){var forward=QualityError(QualitySamples(native,Matrix4x4.identity),TriangleTree.ForMesh(candidate,Matrix4x4.identity));var reverse=QualityError(QualitySamples(candidate,Matrix4x4.identity),TriangleTree.ForMesh(native,Matrix4x4.identity));return new JObject{["passed"]=WithinQuality(forward)&&WithinQuality(reverse),["sourceToCandidate"]=forward,["candidateToSource"]=reverse,["maxLimitMetres"]=.003f,["p95LimitMetres"]=.0005f,["freshMeasurement"]=true,["metric"]="existing bidirectional sampled vertex/centroid distance in actual equipped WORLD metres"};}
static JObject FcoDonorContact(FcoDonorRig rig,Mesh garment){var body=ActorBodyResolver.ResolveOrNull(rig.Body.transform);var result=EnvelopeProbeResidualDispatchedDraft(garment.vertices,garment.triangles,WardrobeBodyVolume.For(TriangleTree.ForRenderer(body)),.002f);return new JObject{["acceptance"]=false,["diagnosticOnly"]=true,["strictPhysical2mmResult"]=result,["noAutomaticFallbackOrWaiver"]=true};}
static AnimationClip FcoDonorClip(string file){var clips=AssetDatabase.LoadAllAssetsAtPath("Assets/ImportedActors/AnimLibrary/"+file).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__",StringComparison.Ordinal)).ToArray();if(clips.Length==0)throw new InvalidOperationException("Missing real runtime clip "+file);return clips[0];}
static JObject FcoDonorGraphics(FcoDonorRig rig,string directory,string stamp,string mode){var result=new JObject();foreach(bool back in new[]{false,true}){string key="fco-donor-"+stamp+"-"+mode+(back?"-back":"-front");RenderWardrobe(rig.Body,key,back);string path=directory+"/"+key+".png";File.Copy(OutputRoot+"/review/"+key+".png",path,false);result[back?"back":"front"]=path;result[(back?"back":"front")+"SHA256"]=FinalFileSHA(path);foreach(string detail in new[]{"sole","cuff"}){string close=directory+"/"+key+"-"+detail+".png";FcoDonorCloseGraphics(rig,close,back,detail=="cuff");result[(back?"back":"front")+"-"+detail]=close;result[(back?"back":"front")+"-"+detail+"SHA256"]=FinalFileSHA(close);}}return result;}
// Same per-material MPB priority as canonical RenderWardrobe, including body
// cutout masks. These are actual runtime renderer properties, not guessed art.
static void FcoDonorCloseGraphics(FcoDonorRig rig,string path,bool back,bool cuff){if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)throw new InvalidOperationException("Graphics required");bool async=ShaderUtil.allowAsyncCompilation;ShaderUtil.allowAsyncCompilation=false;var preview=new PreviewRenderUtility();var meshes=new List<Mesh>();try{var parts=new List<(Mesh mesh,Matrix4x4 matrix,Material[] materials,MaterialPropertyBlock[] blocks)>();foreach(var skin in rig.Body.GetComponentsInChildren<SkinnedMeshRenderer>(true)){if(!skin.enabled||!skin.gameObject.activeInHierarchy)continue;var mesh=new Mesh();skin.BakeMesh(mesh,true);meshes.Add(mesh);var materials=skin.sharedMaterials;var blocks=new MaterialPropertyBlock[materials.Length];for(int i=0;i<blocks.Length;i++){blocks[i]=new MaterialPropertyBlock();skin.GetPropertyBlock(blocks[i],i);if(blocks[i].isEmpty)skin.GetPropertyBlock(blocks[i]);}parts.Add((mesh,skin.transform.localToWorldMatrix,materials,blocks));}var world=FcoDonorCapture(rig.Skin);meshes.Add(world);var bounds=world.bounds;var center=bounds.center;center.y=cuff?bounds.max.y-bounds.size.y*.12f:bounds.min.y+bounds.size.y*.16f;var camera=preview.camera;camera.orthographic=true;camera.orthographicSize=cuff?.17f:.19f;camera.transform.position=center+new Vector3(back?-.14f:.14f,.035f,back?-.9f:.9f);camera.transform.LookAt(center);camera.nearClipPlane=.01f;camera.farClipPlane=10;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.13f,.15f,.17f);preview.lights[0].intensity=1.15f;preview.lights[0].transform.rotation=Quaternion.Euler(35,back?0:180,0);preview.lights[1].intensity=.55f;preview.lights[1].transform.rotation=Quaternion.Euler(-15,back?160:-30,0);for(int pass=0;pass<2;pass++){preview.BeginStaticPreview(new Rect(0,0,768,768));foreach(var part in parts)for(int i=0;i<part.mesh.subMeshCount;i++){int m=Mathf.Min(i,part.materials.Length-1);preview.DrawMesh(part.mesh,part.matrix,part.materials[m],i,part.blocks[m]);}camera.Render();var image=preview.EndStaticPreview();if(pass==1)File.WriteAllBytes(path,image.EncodeToPNG());Object.DestroyImmediate(image);}}finally{foreach(var mesh in meshes)Object.DestroyImmediate(mesh);preview.Cleanup();ShaderUtil.allowAsyncCompilation=async;}}
public static void AuditFcoSourcePreservedDonorEvidence(){const string id="FCO Boots Male";string stamp=DateTime.UtcNow.ToString("yyyyMMddTHHmmssfff"),directory=OutputRoot+"/fco-donor-source-evidence-"+stamp;Directory.CreateDirectory(directory);var cache=JObject.Parse(File.ReadAllText(PreparedRoot+"/preparation.json"));using var input=new FinalFitInput(id,(JObject)cache[id],"donor-evidence-only");if(input.Donor!="Kshishtof")throw new InvalidOperationException("FCO authored donor changed");var native=AssetDatabase.LoadAssetAtPath<GameObject>(input.NativeSource);var sourceFiles=new[]{input.NativeSource,input.BasePrefabPath,PreparedRoot+"/preparation.json",PreparedRoot+"/catalog.json"};var hashes=sourceFiles.ToDictionary(p=>p,FinalFileSHA);var deps=sourceFiles.ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p).ToString());var rows=new JArray();var report=new JObject{["diagnosticCompleted"]=false,["id"]=id,["actor"]="Kshishtof",["equipmentFactory"]="BodyBones.Equip",["rootScale"]=.7764706f,["rows"]=rows,["noSolverExecuted"]=true,["acceptanceOverride"]=false,["fallbackAcceptanceGranted"]=false,["nativeSettings"]=Settings(native.GetComponent<Wear>()),["baseSettings"]=Settings(input.BasePrefab.GetComponent<Wear>())};
try{using var source=new FcoDonorRig(native);using var candidate=new FcoDonorRig(input.BasePrefab);var idle=FcoDonorClip("Male@Idle.fbx");var run=FcoDonorClip("Male@Run.fbx");var sleep=FcoDonorClip("Sleep.fbx");var belly=FcoDonorClip("LayingBelly.anim");var poses=new[]{("standing",idle,.4f,false),("run_early",run,.1f,false),("run_mid",run,.45f,false),("run_late",run,.8f,false),("sleep",sleep,.5f,true),("belly",belly,.5f,true)};bool allQuality=true,allMovement=true;Vector3[] standingBody=null;foreach(var pose in poses){foreach(var rig in new[]{source,candidate})rig.Body.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);int sourceCalls=source.Pose(pose.Item2,pose.Item3,pose.Item4),candidateCalls=candidate.Pose(pose.Item2,pose.Item3,pose.Item4);float poseMotion=0;var actualBodyMesh=FcoDonorCapture(ActorBodyResolver.ResolveOrNull(source.Body.transform));try{var localBody=actualBodyMesh.vertices.Select(source.Body.transform.InverseTransformPoint).ToArray();if(pose.Item1=="standing")standingBody=localBody;else if(pose.Item1.StartsWith("run_",StringComparison.Ordinal)){for(int i=0;i<localBody.Length;i++)poseMotion=Mathf.Max(poseMotion,Vector3.Distance(localBody[i],standingBody[i]));if(poseMotion<=.01f)throw new InvalidOperationException("Real imported run clip did not drive actual body: "+pose.Item1);}}finally{Object.DestroyImmediate(actualBodyMesh);}var a=FcoDonorCapture(source.Skin);var b=FcoDonorCapture(candidate.Skin);try{var row=new JObject{["pose"]=pose.Item1,["clip"]=AssetDatabase.GetAssetPath(pose.Item2),["clipTime"]=pose.Item2.length*pose.Item3,["actualBodyMotionFromStandingMetres"]=poseMotion,["actualHeelLateUpdateCallsNative"]=sourceCalls,["actualHeelLateUpdateCallsBase"]=candidateCalls,["unscaledDeltaTime"]=Time.unscaledDeltaTime,["nativeHeelWeight"]=source.Bones.HeelPoseWeight,["baseHeelWeight"]=candidate.Bones.HeelPoseWeight,["quality"]=FcoDonorFreshQuality(a,b),["nativeContactDiagnostic"]=FcoDonorContact(source,a),["baseContactDiagnostic"]=FcoDonorContact(candidate,b)};allQuality&=(bool)row["quality"]["passed"];if(pose.Item1=="standing"){row["nativeImages"]=FcoDonorGraphics(source,directory,stamp,"Native");row["baseImages"]=FcoDonorGraphics(candidate,directory,stamp,"BASE");}var localA=a.vertices.Select(source.Body.transform.InverseTransformPoint).ToArray();var localB=b.vertices.Select(candidate.Body.transform.InverseTransformPoint).ToArray();foreach(var rig in new[]{source,candidate})rig.Body.transform.SetPositionAndRotation(new Vector3(13.25f,2.1f,-8.75f),Quaternion.Euler(0,137,0));var ma=FcoDonorCapture(source.Skin);var mb=FcoDonorCapture(candidate.Skin);try{row["movedQuality"]=FcoDonorFreshQuality(ma,mb);allQuality&=(bool)row["movedQuality"]["passed"];row["nativeRootEquivariance"]=RetargetProbeError(localA.Select(source.Body.transform.TransformPoint).ToArray(),ma.vertices);allMovement&=(float)row["nativeRootEquivariance"]["maxMetres"]<.0003f;row["baseRootEquivariance"]=RetargetProbeError(localB.Select(candidate.Body.transform.TransformPoint).ToArray(),mb.vertices);allMovement&=(float)row["baseRootEquivariance"]["maxMetres"]<.0003f;}finally{Object.DestroyImmediate(ma);Object.DestroyImmediate(mb);}rows.Add(row);File.WriteAllText(directory+"/fco-donor-evidence.json",report.ToString());}finally{Object.DestroyImmediate(a);Object.DestroyImmediate(b);}}
foreach(var rig in new[]{source,candidate}){rig.Body.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);rig.Pose(idle,.4f,false);}var beforeNative=source.Bones.GetWorn("fco-evidence");var beforeBase=candidate.Bones.GetWorn("fco-evidence");source.Bones.TakeOff("fco-evidence");candidate.Bones.TakeOff("fco-evidence");if(source.Bones.GetWorn("fco-evidence")!=null||candidate.Bones.GetWorn("fco-evidence")!=null)throw new InvalidOperationException("TakeOff retained gear");source.Equip();candidate.Equip();source.Pose(idle,.4f,false);candidate.Pose(idle,.4f,false);var ra=FcoDonorCapture(source.Skin);var rb=FcoDonorCapture(candidate.Skin);try{report["reequip"]=new JObject{["newNativeInstance"]=!ReferenceEquals(beforeNative,source.Bones.GetWorn("fco-evidence")),["newBaseInstance"]=!ReferenceEquals(beforeBase,candidate.Bones.GetWorn("fco-evidence")),["quality"]=FcoDonorFreshQuality(ra,rb)};allQuality&=(bool)report["reequip"]["quality"]["passed"];}finally{Object.DestroyImmediate(ra);Object.DestroyImmediate(rb);}report["rootTranslationYawEquivarianceAllSixPosesPassed"]=allMovement;report["freshQualityAllSixPosesMovedRootsAndReequipPassed"]=allQuality;report["diagnosticCompleted"]=true;}
finally{bool unchanged=true;foreach(var p in sourceFiles)unchanged&=FinalFileSHA(p)==hashes[p]&&AssetDatabase.GetAssetDependencyHash(p).ToString()==deps[p];report["sourceAssetsUnmodified"]=unchanged;report["sourceFileSHA256"]=JObject.FromObject(hashes);report["dependencyHashes"]=JObject.FromObject(deps);File.WriteAllText(directory+"/fco-donor-evidence.json",report.ToString());if(!unchanged)throw new InvalidOperationException("Evidence changed source assets");}Debug.Log("FCO_DONOR_SOURCE_EVIDENCE_READY "+directory);}
